// header: extern Stream& stream; static StreamInitializer streamInit;
static int nifty_counter;                     // zero-initialized at load
static std::aligned_storage<sizeof(Stream), alignof(Stream)>::type buf;
Stream& stream = reinterpret_cast<Stream&>(buf);
StreamInitializer::StreamInitializer() { if (nifty_counter++ == 0) new (&stream) Stream(); }
StreamInitializer::~StreamInitializer() { if (--nifty_counter == 0) stream.~Stream(); }
